using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Export;using ToneCustoms.ShellStudio.Validation;using Xunit;
namespace ToneCustoms.ShellStudio.Tests;
public class CoreTests { [Fact]public void GridSnapWorks(){var g=new GeometryService();var v=g.Snap(new(1.12f,.61f,.1f),.25f);Assert.Equal(1,v.X);Assert.Equal(.5f,v.Y);Assert.Equal(0,v.Z);}[Fact]public void WallHasExpectedType()=>Assert.Equal(SceneObjectType.Wall,new GeometryService().Wall(new()).Type);[Fact]public void EmptyProjectWarns()=>Assert.Contains(new ProjectValidator().Validate(new()),x=>x.Area=="Geometry");[Fact]public void BuilderCreatesManifest(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());var r=new FiveMResourceBuilder().Prepare(new(){Name="test_shell"},root);Assert.True(File.Exists(Path.Combine(r,"fxmanifest.lua")));Directory.Delete(root,true);} }
